update help_articles set purpose='Everything about one job: assignments, visits, reports, photos, defects, paperwork, messages, sign-off and history.

Layout: tabs Overview, Reports, Photos, Defects, Paperwork and Activity; Emails, Parts and Survey & Snags sit behind More. Office staff get one main button chosen by the job''s stage (Fill in report, Send to customer, Create invoice), next to Send to Customer. The Send to Customer window lets you pick attachments, check the recipient and message, and shows a Before you send summary. Status changes are internal: nothing goes to the customer unless an admin has switched on an automatic email in Settings → Email.', steps='[{"heading": "Find your way around", "items": ["Tabs: Overview, Reports, Photos, Defects, Paperwork and Activity.", "More (beside the tabs): Emails, Parts, Survey & Snags, each with a count or an empty hint.", "Reports: the job''s reports, one line per riser, plus Add another report and Convert to digital report.", "Defects: the job''s defects, tick boxes for bulk Chargeable / No charge, Quote selected and Add to next service report.", "Paperwork: RAMS, attached and reference documents, certificates and Sign-off (signatures and remote sign-off links).", "Activity: messages, activity and timeline together, with an All / Activity / Timeline filter, newest first.", "The tab you last used is remembered on every job. Old links to Documents open Reports, Sign-off opens Paperwork, History opens Activity."]}, {"heading": "The main button changes with the job''s stage", "items": ["Office staff see one main button at the top, chosen by the job''s status.", "Before the work is done (booked, scheduled, active and so on): Fill in report, which opens the Reports tab.", "Pending review: Send to customer is the main step, using the Send to Customer button beside it.", "Completed or archived: Create invoice.", "Cancelled: no main button.", "Everything else is under More at the top: AI Brief, Export PDF/Word, Print for site, Jump to sign-off, Clone job, Schedule follow-up, Create Quote."]}, {"heading": "Send to Customer window", "items": ["Press Send to Customer (top of the job). Nothing is sent until you press Send Email.", "Tick what to attach: Customer report, RAMS / compliance docs, Job sheets, and an invoice or quote if there is one.", "Check the customer email, subject and message.", "Choose how it goes: Send from your Microsoft 365 mailbox, Create a draft in Outlook, or the Servexa mailer.", "The Before you send box shows exactly who it''s going to and what is attached.", "Report PDFs are rebuilt from the latest saved report each time you send."]}, {"heading": "Completing a job is internal", "items": ["Marking a job Complete (or any other status) sends nothing to the customer.", "You''ll see: Job marked complete (internal). Nothing was sent to the customer, with a Send to customer link.", "To email customers automatically, an admin can switch it on in Settings → Email → Automatic customer emails (all off by default)."]}, {"heading": "Assign an engineer", "items": ["Open Assignments on the Overview tab.", "Click Assign Engineer and pick from the list.", "The engineer sees the job on their dashboard and in Today''s Visits."]}, {"heading": "Print paper sheets", "items": ["More → Print for site.", "On riser jobs, Print reports and Print sticker pack sit in the top button row (admin only)."]}]'::jsonb,
 common_problems = '[{"problem": "I can''t find AI Brief / Export / Print for site", "fix": "They''re under More at the top of the job."}, {"problem": "I can''t find the Documents or Sign-off tab", "fix": "Reports are now on the Reports tab; Sign-off is at the bottom of the Paperwork tab."}, {"problem": "I can''t find Fill in report / Create invoice", "fix": "The main button follows the job''s status: Fill in report before the work is done, Create invoice once completed. Change the status if it shows the wrong one."}, {"problem": "The customer got no email when I completed the job", "fix": "That''s intended. Use Send to Customer, or ask an admin to switch on the completion email in Settings → Email."}]'::jsonb || coalesce((select jsonb_agg(e) from jsonb_array_elements(common_problems) e where jsonb_typeof(e) <> 'object' or coalesce(e->>'problem','') not ilike '%AI Brief%'),'[]'::jsonb),
 keywords = (select array(select distinct unnest(keywords || array['reports tab','paperwork tab','defects tab','activity tab','main button','fill in report','create invoice','send to customer','before you send','completion email','internal status']))),
 last_updated=now() where slug='jobs.detail';